le_id']); ?>"><?php echo lorkhan_ui_h($row['name']); ?></option><?php endforeach; ?></select></label><label>Name<input name="name" required maxlength="256"></label><input type="hidden" name="content_json" value="{}"></div><div class="lorkhan-actions"><button type="submit">Create Playthrough</button></div></form></details>
<details class="lorkhan-card"><summary>Import playthrough snapshot</summary><p>Import conversation, memory, relationship and knowledge records into the selected playthrough. This does not restore a game save or replace the complete server database.</p><form method="post" action="<?php echo lorkhan_ui_h($managementBasePath); ?>/forms/playthrough-import"><input type="hidden" name="_csrf" value="<?php echo lorkhan_ui_h($csrf); ?>"><div class="lorkhan-form-grid"><label>Installation<select name="installation_id"><?php foreach($installations as$row): ?><option value="<?php echo lorkhan_ui_h($row['installation_id']); ?>"><?php echo lorkhan_ui_h($row['display_name']); ?></option><?php endforeach; ?></select></label><label>Profile<select name="profile_id"><?php foreach($profiles as$row): ?><option value="<?php echo lorkhan_ui_h($row['profile_id']); ?>"><?php echo lorkhan_ui_h($row['name']); ?></option><?php endforeach; ?></select></label><label>Destination playthrough<select name="playthrough_id"><?php foreach($rows as$row): ?><option value="<?php echo lorkhan_ui_h($row['playthrough_id']); ?>"><?php echo lorkhan_ui_h($row['playthrough']); ?></option><?php endforeach; ?></select></label><label class="wide">Snapshot file<input type="file" id="playthrough-snapshot-file" accept=".json,application/json"><span id="playthrough-file-status" role="status"></span></label><details class="wide"><summary>Advanced: paste snapshot JSON</summary><label>Snapshot JSON<textarea id="playthrough-snapshot-json" name="playthrough_json" rows="8"></textarea></label></details></div><div class="lorkhan-actions"><button type="submit">Import Snapshot</button></div></form></details>
